    if (DATA.wb[k]) return DATA.wb[k];
    /* (bản 2026.11.11-7) màn boss thế giới gồm TẤT CẢ từ của các kho trong giai đoạn; mỗi đợt = toàn bộ quái của 1 kho (đếm như khi chơi kho đó) */
